import { Task } from '../../domain/entities/Task';
import { NotFoundError } from '../../domain/errors/DomainError';
import { ProjectRepository } from '../../domain/repositories/ProjectRepository';
import { TaskRepository } from '../../domain/repositories/TaskRepository';
import { IdGenerator } from '../../domain/services/IdGenerator';
import { DueDate } from '../../domain/value-objects/DueDate';
import { TaskStatus } from '../../domain/value-objects/TaskStatus';
import { TaskTitle } from '../../domain/value-objects/TaskTitle';
import { CreateTaskInput, TaskDto, toTaskDto } from '../dtos/TaskDtos';

export class CreateTaskUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
    private readonly ids: IdGenerator,
  ) {}

  async execute(input: CreateTaskInput): Promise<TaskDto> {
    const project = await this.projects.findById(input.projectId);
    if (!project) {
      throw new NotFoundError('Project', input.projectId);
    }

    const task = Task.create({
      id: this.ids.next(),
      projectId: project.id,
      title: TaskTitle.create(input.title),
      description: input.description,
      dueDate: input.dueDate === undefined ? undefined : DueDate.fromIsoString(input.dueDate),
      status: input.status === undefined ? undefined : TaskStatus.from(input.status),
    });

    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

